// ---- V3: metamorphic validator ----
const SWAP = { brl: 'eur', usd: 'eur', eur: 'gbp', gbp: 'eur', real: 'euro', dolar: 'euro', 'dólar': 'euro', dollar: 'euro', euro: 'libra', libra: 'euro', pound: 'euro' };
