  if (newId && a.idSpans.length) {
    const o2 = safeRun(run, replaceSpans(raw, a.idSpans.map(s => ({ ...s, text: newId }))));
    if (!o2 || o2.audit_id !== newId || !sameExcept(out, o2, ['audit_id'])) return false;
  }

